UPDATE camunda_highlight_record
SET assignee = #{assignee}
WHERE id = (
    SELECT id FROM (
        SELECT id FROM camunda_highlight_record
        WHERE process_instance_id = #{processInstanceId}
          AND element_id = #{elementId}
        ORDER BY create_time DESC, id DESC
        LIMIT 1
    ) tmp
)

